from taf.ul.kpi_selector.operations.site_reset.classical_site_reset.site_reset_prototype import SiteReset


class SiteReset22R1(SiteReset):

    def get_kpi(self):  # noqa: C901
        """
        Gets kpi for site reset operation.
        :return: dictionary with timeout, requirement and operation description for site reset
        :rtype: dict
        """
        use_restrictions = True
        if all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),
                    self.bts.number_of_bbmods == 1,
                    self.bts.number_of_nr_cells <= 6,
                    self.bts.number_of_rmods == 1,
                    self.bts.cell_technologies == "TDD",
                    self.bts.setup_mode == "NSA+SA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 468
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13707"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),
                    self.bts.number_of_bbmods == 1,
                    self.bts.number_of_nr_cells <= 3,
                    self.bts.number_of_rmods <= 3,
                    self.bts.number_of_smods == 1,
                    self.bts.cell_technologies == "FDD",
                    self.bts.setup_mode == "NSA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 468
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13726"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),  # same for 22r2
                    self.bts.number_of_bbmods <= 2,
                    self.bts.number_of_nr_cells <= 6,
                    self.bts.number_of_rmods <= 6,
                    self.bts.number_of_smods == 1,
                    self.bts.cell_technologies == "TDD",
                    self.bts.setup_mode == "NSA+SA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 468
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13473"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),  # same for 22r2
                    self.bts.number_of_bbmods <= 3,
                    self.bts.number_of_nr_cells <= 9,
                    self.bts.number_of_rmods <= 3,
                    self.bts.number_of_smods == 1,
                    self.bts.cell_technologies == "TDD",
                    self.bts.setup_mode == "NSA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 468
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13500"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),  # same for 22r2
                    self.bts.number_of_bbmods <= 3,
                    self.bts.number_of_nr_cells <= 24,
                    self.bts.number_of_rmods <= 3,
                    self.bts.number_of_smods == 1,
                    self.bts.cell_technologies == "TDD",
                    self.bts.setup_mode == "NSA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 468
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13482"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),  # same for 22r2
                    self.bts.number_of_bbmods <= 1,
                    self.bts.number_of_nr_cells <= 3,
                    self.bts.number_of_rmods <= 3,
                    self.bts.cell_technologies == "FDD",
                    self.bts.setup_mode == "NSA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 468
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13706"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),
                    self.bts.number_of_bbmods == 1,
                    self.bts.number_of_nr_cells <= 8,
                    self.bts.number_of_rmods <= 6,
                    self.bts.number_of_smods == 1,
                    self.bts.cell_technologies == "FDD",
                    self.bts.setup_mode == "NSA+SA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 468
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13717"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),
                    self.bts.number_of_bbmods <= 3,
                    self.bts.number_of_smods == 1,
                    self.bts.number_of_nr_cells <= 8,
                    self.bts.number_of_rmods <= 6,
                    self.bts.cell_technologies == "MIX",
                    self.bts.setup_mode == "NSA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 468
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13744"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIO"]),
                    self.bts.number_of_bbmods <= 3,
                    self.bts.number_of_nr_cells <= 6,
                    self.bts.number_of_rmods <= 6,
                    self.bts.cell_technologies == "TDD",
                    self.bts.setup_mode == "NSA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 468
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13842"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIL"]),  # same for 22r2
                    self.bts.number_of_bbmods <= 3,
                    self.bts.number_of_nr_cells <= 3,
                    self.bts.number_of_rmods <= 3,
                    self.bts.number_of_smods == 1,
                    self.bts.cell_technologies == "TDD",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 360
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13509"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIO"]),  # same for 22r2
                    self.bts.number_of_bbmods == 1,
                    self.bts.number_of_nr_cells <= 6,
                    self.bts.number_of_rmods <= 6,
                    self.bts.cell_technologies == "FDD",
                    self.bts.setup_mode == "SA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 360
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13833"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIO"]),  # same for 22r2
                    self.bts.number_of_bbmods <= 3,
                    self.bts.number_of_smods == 1,
                    self.bts.number_of_nr_cells <= 18,
                    self.bts.cell_technologies == "FDD",
                    self.bts.number_of_rmods <= 18,
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 360
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13522"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIO"]),  # same for 22r2
                    self.bts.number_of_bbmods <= 3,
                    self.bts.number_of_nr_cells <= 18,
                    self.bts.number_of_smods == 1,
                    self.bts.number_of_rmods <= 2,
                    self.bts.cell_technologies == "TDD",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 360
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13535"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIO"]),  # same for 22r2
                    self.bts.number_of_bbmods <= 2,
                    self.bts.number_of_nr_cells <= 12,
                    self.bts.number_of_rmods <= 6,
                    self.bts.cell_technologies == "TDD",
                    self.bts.setup_mode == "SA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 360
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13851"

        elif all(
                [
                    "ASOE" in self.bts.smod_hw_types,  # same for 22r2
                    self.bts.number_of_nr_cells <= 3,
                    self.bts.number_of_rmods == 1,
                    self.bts.cell_technologies == "TDD",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 360
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13860"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIK", bbmod_types=["ABIL"]),  # same for 22r2
                    self.bts.is_full_rack,
                    self.bts.number_of_bbmods <= 6,
                    self.bts.number_of_nr_cells <= 9,
                    self.bts.number_of_rmods <= 2,
                    self.bts.cell_technologies in ["MIX", "TDD"],
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 504
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13548"

        elif all(
                [
                    self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIO"]),  # same for 22r2
                    self.bts.is_full_rack,
                    self.bts.number_of_bbmods <= 6,
                    self.bts.number_of_nr_cells <= 6,
                    self.bts.cell_technologies == "TDD",
                    self.bts.number_of_rmods <= 2,
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 504
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13574"

        else:
            return super(SiteReset22R1, self).get_kpi()

        if use_restrictions:
            self.operation_details["Timeout"] += self.restrictions.use_restrictions_from_OM_GEN_SFS_PERF_CAP_13441()

        return self.operation_details
